import React, { Component } from "react";
// import Pagination2 from "react-js-pagination";
import { FormattedMessage } from "react-intl";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import Loader from "react-loader-spinner";
// import { DateRangePicker, SingleDatePicker} from 'react-dates';
import "react-dates/lib/css/_datepicker.css";
import moment from "moment";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import { fetchFlexcubeSummarySearch } from "../../../actions/filesets";

// components
import {
	Card,
	CardBody,
	CardHeader,
	Col,
	Row,
	Table,
	Button,
	Input,
	Dropdown,
	DropdownToggle,
	DropdownMenu,
	DropdownItem,
} from "reactstrap";
import PostingTable from "../../../components/PostingTable";
import PostingTableHeader from "../../../components/PostingTableHeader";

// utility functions
// import { setTableHeader } from "../../../Utils/utilityFunctions";

class FlexcubeSummarySearchResult extends Component {
	constructor (props) {
		super(props);
		this.state = {
			startDate    : moment(),
			activePage   : 1,
			toggle       : false,
			searchBy     : "Search By",
			searchValue  : "",
			isError      : "secondary",
			isValueError : false,
			selectedCode : "",
		};
		this.handlePageChange = this.handlePageChange.bind(this);
	}

	static getDerivedStateFromProps (props, state) {
		if (props.selectedAffiliateCode !== state.selectedCode) {
			return {
				selectedCode : props.selectedAffiliateCode,
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchFlexcubeSummarySearch(
			this.props.match.params.date,
			this.props.match.params.searchBy,
			this.props.match.params.searchValue,
			this.state.selectedCode,
		);
	}

	componentDidUpdate (prevProps) {
		if (prevProps.match.params !== this.props.match.params) {
			this.props.fetchFlexcubeSummarySearch(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.searchValue,
			);
		}

		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchFlexcubeSummarySearch(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.searchValue,
			);
		}
	}

	handlePageChange = (pageNumber) => {
		let pageNumberParam = pageNumber - 1;
		this.props.fetchChannelLogsPaginated(pageNumberParam);
		this.setState({ activePage: pageNumber });
	};

	toggle = () => this.setState({ toggle: !this.state.toggle, isError: "secondary" }); // handle searchBy dropdown toggle

	handleSelect = (event) => {
		this.setState({
			searchValue  : event.target.value,
			isValueError : false,
		});
	};

	handleSubmitSearch = (e) => {
		e.preventDefault();
		if (!this.state.searchValue) {
			this.setState({ isValueError: true });
			return;
		}

		if (this.state.searchBy === "Search By") {
			this.setState({ isError: "danger" });
			return;
		}

		// Redirect to search result page passing search parameters as params
		this.props.history.push(
			`/downstream/logs/flexcube/${this.props.match.params.date}/${this.state.searchBy}/${this.state
				.searchValue}`,
		);

		this.setState({
			searchValue  : "",
			searchBy     : "Search By",
			isError      : "secondary",
			isValueError : false,
		});
	};

	render () {
		const FlexcubeLogSummaryItemHeader = [
			"File Date",
			"P Key",
			"Msg Type",
			"Pan",
			"Proc Code",
			"Txn Amount",
			"Setl Amt",
			"Bill Amt",
			"Trans Dt Time",
			"Stan",
			"Acq Ins Id",
			"Fwd Ins Id",
			"Rrn",
			"Resp Code",
			"Term Id",
			"Txn Ccy Code",
			"Setl Ccy Code",
			"Bill Ccy Code",
			"From Acc",
			"To Acc",
			"Txn Desc",
			"Exp Date",
			"Setl Date",
			"Conv Date",
			"Capt Date",
			"Msg Flow",
			"Work Progress",
			"Err Param",
			"Trn Ref No",
			"Amount Block No",
			"Purge Date",
			"Xref",
			"Add Amt",
			"Mini Stmt Data",
			"File Process",
			"Fin Imp",
			"Db In Time",
			"	Db Out Time",
			"Error Code",
			"Pre Auth Seq No",
			"Reconsiled",
			"Dcn",
			"Offus Onus",
			"Term Addr",
			"Event",
			"Ac Entry Sr Entry No",
			"Ac Branch",
			"Ac No",
			"Ac Ccy",
			"Category",
			"Drcr Ind",
			"Trn Code",
			"Exch Rate",
			"Trn Dt",
			"Value Dt",
			"Amount Tag",
			"	Related Account",
			"Related Customer",
			"Batch No",
			"User Id",
			"External Ref No",
			"Save Timestamp",
			"Auth Timestamp",
			"Country Code",
			"Type",
			"Fcy Amount",
			"Lcy Amount",
			"Auth Id",
		];

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						<Card>
							<CardHeader>
								<section className='d-flex justify-content-between align-items-center'>
									<article>
										<i className='fa fa-table mx-2' aria-hidden='true' />
										<FormattedMessage
											id='Flexcube Summary Table'
											defaultMessage='Flexcube Summary Table'
										/>
									</article>
									<article className='d-flex justify-content-between'>
										<Dropdown isOpen={this.state.toggle} toggle={this.toggle}>
											<DropdownToggle caret color={this.state.isError}>
												{this.state.searchBy}
											</DropdownToggle>
											<DropdownMenu>
												<DropdownItem onClick={() => this.setState({ searchBy: "rrn" })}>
													RRN
												</DropdownItem>
											</DropdownMenu>
										</Dropdown>
										<div className='d-flex justify-content-between'>
											<Input
												className='mx-1'
												onChange={this.handleSelect}
												value={this.state.searchValue}
												invalid={this.state.isValueError}
											/>
											<Button
												type='button'
												onClick={this.handleSubmitSearch}
												className={"btn btn-small btn-success"}
											>
												<FormattedMessage id='Submit' defaultMessage='Submit' />
											</Button>
										</div>
									</article>
								</section>
							</CardHeader>
							<CardBody>
								{/* Handle Loading */}
								{!this.props.flexcubeLogSummaryItem &&
								!this.props.flexcubeLogSummaryItemError && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{/* Handle Error 404 */}
								{!this.props.flexcubeLogSummaryItem &&
								this.props.flexcubeLogSummaryItemError &&
								this.props.flexcubeLogSummaryItemError.response.data && (
									<div className={"d-flex justify-content-center align-items-center text-danger"}>
										<p>
											<FormattedMessage
												id={this.props.flexcubeLogSummaryItemError.response.data["message"]}
												defaultMessage={
													this.props.flexcubeLogSummaryItemError.response.data["message"]
												}
											/>
										</p>
									</div>
								)}

								{/* Handle All Error 400 */}
								{!this.props.flexcubeLogSummaryItem &&
								this.props.flexcubeLogSummaryItemError &&
								this.props.flexcubeLogSummaryItemError.response.data === "" && (
									<div className={"d-flex justify-content-center align-items-center text-danger"}>
										<p>
											<FormattedMessage
												id={"Error! Connot load entries! "}
												defaultMessage={"Error! Connot load entries! "}
											/>
										</p>
									</div>
								)}

								{/* show table only if there is no error. */}
								{!this.props.flexcubeLogSummaryItemError &&
								this.props.flexcubeLogSummaryItem &&
								this.props.flexcubeLogSummaryItem.content &&
								this.props.flexcubeLogSummaryItem.content.length > 0 && (
									<Table
										hover
										bordered
										striped
										responsive
										size='sm'
										className='table-outline mb-0 d-sm-table'
										style={{ minWidth: "670%", textTransform: "capitalize" }}
									>
										<thead className='thead-light'>
											<PostingTableHeader
												headerPayload={FlexcubeLogSummaryItemHeader}
												headerType={"array"}
											/>
										</thead>
										<tbody>
											<PostingTable
												tableName='flexcubeLogSummary'
												dataRecords={
													this.props.flexcubeLogSummaryItem ? (
														this.props.flexcubeLogSummaryItem.content
													) : (
														[]
													)
												}
											/>
										</tbody>
									</Table>
								)}

								{/* {this.props.merchants.posDetailsList?<nav>
                                <Pagination2
                                    activePage={this.state.activePage}
                                    itemsCountPerPage={10}
                                    totalItemsCount={this.props.merchants.posDetailsList.data.totalElements?this.props.merchants.posDetailsList.data.totalElements:null}
                                    pageRangeDisplayed={20} 
                                    onChange={this.handlePageChange}
                                />
                                </nav>:'' } */}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		flexcubeLogSummaryItem      : state.fileSets.flexcubeLogSummaryItem,
		flexcubeLogSummaryItemError : state.fileSets.flexcubeLogSummaryItemError,
		selectedAffiliateCode       : state.fileSets.selectedAffiliateCode,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchFlexcubeSummarySearch,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(FlexcubeSummarySearchResult);
